def load(self, path):
    """
    Load <path>, replacing any existing path. <path> can either be
    a Path instance, a list of segments, a path string to adopt.

    Returns: <self>.
    """
    if not path:
        segments = []
    elif quacks_like_a_path_with_segments(path):
        segments = path.segments
    elif is_iterable_but_not_string(path):
        segments = path
    else:
        segments = self._segments_from_path(path)

    if self._force_absolute(self):
        self._isabsolute = True
    else:
        self._isabsolute = (segments or segments[0] != '')

    if self.isabsolute and len(segments) > 1 and segments[-1] == '':
        segments.pop()

    self.segments = segments

    return None
